$$
\begin{array}{r l} I _ {n} & = \int \frac {\mathrm{d} x}{\sin^ {n} x} = \int \frac {\sin^ {2} x + \cos^ {2} x}{\sin^ {n} x} \mathrm{d} x = I _ {n - 2} - \frac {1}{n - 1} \int \cos x \mathrm{d} \left(\frac {1}{\sin^ {n - 1} x}\right) \\ & = I _ {n - 2} - \frac {\cos x}{(n - 1) \sin^ {n - 1} x} - \frac {1}{n - 1} I _ {n - 2} = - \frac {\cos x}{(n - 1) \sin^ {n - 1} x} + \frac {n - 2}{n - 1} I _ {n - 2} \end{array}

\begin{array}{r l} I _ {5} & = \int \frac {\mathrm{d} x}{\sin^ {5} x} = - \frac {\cos x}{4 \sin^ {4} x} + \frac {3}{4} I _ {3} = - \frac {\cos x}{4 \sin^ {4} x} + \frac {3}{4} \cdot \left(- \frac {\cos x}{2 \sin^ {2} x} + \frac {1}{2} I _ {1}\right) \\ & = - \frac {\cos x}{4 \sin^ {4} x} - \frac {3 \cos x}{8 \sin^ {2} x} + \frac {3}{8} \ln \left| \tan \frac {x}{2} \right| + C \end{array}
$$
